// ─────────────────────────────────────────────────────────────────────────────
// ALL Substack-email parsing lives in this one node. If Substack changes its
// "new subscriber" notification template, this is the only thing to fix.
// Every output item carries raw_body_excerpt so mismatches are easy to debug
// from the execution log.
// ─────────────────────────────────────────────────────────────────────────────
const EMAIL_RE = /[A-Z0-9._%+'-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
const IGNORED_DOMAINS = ['substack.com', 'substackmail.com', 'substackcdn.com'];
// Notifications in the label that are not new sign-ups.
const SKIP_SUBJECT_RE = /unsubscribe|cancel|payment failed|refund/i;

const addr = v => String(v || '').trim().toLowerCase();
const listAddrs = field => ((field && field.value) || []).map(x => addr(x.address));
const isIgnoredDomain = email => {
  const domain = email.split('@')[1] || '';
  return IGNORED_DOMAINS.some(d => domain === d || domain.endsWith('.' + d));
};

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const subject = j.subject || '';

  const htmlAsText = j.html
    ? j.html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ')
    : '';
  const body = String(j.text || htmlAsText || '')
    .replace(/&#64;|&#x40;|&commat;|%40/gi, '@')
    .replace(/&amp;/g, '&');

  const own = new Set([
    ...String(j._publisher_emails || '').split(',').map(addr).filter(Boolean),
    ...listAddrs(j.from),
    ...listAddrs(j.to),
  ]);

  const candidates = [...new Set(
    (body.match(EMAIL_RE) || []).map(e => addr(e).replace(/[.'-]+$/, ''))
  )].filter(e => !isIgnoredDomain(e) && !own.has(e));

  const debug = {
    gmail_message_id: j.id,
    subject,
    all_candidates: candidates,
    raw_body_excerpt: body.replace(/\s+/g, ' ').slice(0, 3000),
  };
  console.log('Substack parse', JSON.stringify(debug));

  if (SKIP_SUBJECT_RE.test(subject)) continue;

  if (candidates.length === 0) {
    throw new Error('Could not find a subscriber email in Substack notification. ' + JSON.stringify(debug));
  }

  const email = candidates[0];

  // Substack's notification is not a reliable source for the subscriber's name,
  // so we only sync the email. Names can be filled in Attio by the team.
  const name = null;

  out.push({
    json: {
      email,
      name,
      source: 'Sparx Signal',
      extra_values: {},
      ambiguous: candidates.length > 1,
      attio_assert_body: { data: { values: { email_addresses: [email] } } },
      raw_payload: debug,
      ...debug,
    },
  });
}
return out;

// Runs once per contact. Input = Attio's response to the upsert (PUT assert).
// PATCH on Attio *appends* multi-select values, so adding the source tag never
// removes tags from other sources.
const rec = $input.item.json.data;
const src = $('Parse subscriber email (Substack template)').item.json;
const v = rec.values || {};

const values = { ...(src.extra_values || {}) };

const existingSources = (v.source || []).map(s => s.option && s.option.title);
if (!existingSources.includes(src.source)) values.source = [src.source];

const existingName = (v.name || [])[0];
if (src.name && !(existingName && existingName.full_name)) values.name = [src.name];

return {
  json: {
    record_id: rec.id.record_id,
    email: src.email,
    attio_patch_body: { data: { values } },
  },
};
